from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl_seconds, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock
        self._entries = OrderedDict()  # key -> (value, inserted_at)

    def _is_expired(self, key, now):
        _, inserted_at = self._entries[key]
        return now - inserted_at > self.ttl_seconds

    def get(self, key):
        now = self.clock()
        entry = self._entries.get(key)
        if entry is None:
            return None
        if self._is_expired(key, now):
            del self._entries[key]
            return None
        self._entries.move_to_end(key)  # refresh recency
        return entry[0]

    def put(self, key, value):
        now = self.clock()
        self._entries[key] = (value, now)
        self._entries.move_to_end(key)
        self._evict(now)

    def _evict(self, now):
        # Drop expired entries first; they are not live.
        for key in list(self._entries):
            if self._is_expired(key, now):
                del self._entries[key]
        # Evict least-recently-used live entries until within capacity.
        while len(self._entries) > self.capacity:
            self._entries.popitem(last=False)

